import React from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import Header from './components/Header/Header';
import Footer from './components/Footer/Footer';
import ForumPage from './components/Forum/ForumPage';
import ForumDetail from './components/Forum/ForumDetail';

function App() {
    const forums = [
        {
            id: 1,
            name: "Introductions",
            description: "Introduce yourself to the community.",
            subForums: [
                { id: 11, name: "New Members", description: "Introduce yourself here.", lastThread: { title: "Say Hi!", author: "User123", date: "2024-08-29" } },
                { id: 12, name: "Off-Topic", description: "Talk about anything unrelated.", lastThread: { title: "Random Thoughts", author: "User456", date: "2024-08-30" } }
            ],
        },
        {
            id: 2,
            name: "News",
            description: "Stay updated with the latest news.",
            subForums: [
                { id: 21, name: "Announcements", description: "Official updates.", lastThread: { title: "New Features", author: "Admin", date: "2024-08-28" } },
                { id: 22, name: "Community News", description: "News from the community.", lastThread: { title: "Community Meetup", author: "Mod", date: "2024-08-29" } }
            ],
        }
    ];

    return (
        <Router>
            <Header />
            <main style={{ padding: '20px' }}>
                <Routes>
                    <Route path="/" element={<ForumPage />} />
                    <Route path="/forum/:id" element={<ForumDetail forums={forums} />} />
                </Routes>
            </main>
            <Footer />
        </Router>
    );
}

export default App;
